<?php
namespace App\Http\Controllers\Api\V1;
use App\Contracts\OtpSender;use App\Http\Controllers\Controller;use App\Models\TenantRegistrationRequest;use App\Models\User;use App\Models\VerificationChallenge;use App\Services\ContactIdentity;use App\Services\SensitiveIdentifier;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Support\Facades\Hash;use Illuminate\Support\Str;
class TenantRegistrationController extends Controller{
public function store(Request $r,ContactIdentity $identity,SensitiveIdentifier $sensitive,OtpSender $sender):JsonResponse{$d=$r->validate(['institution_name'=>'required|string|max:200','legal_name'=>'nullable|string|max:250','requested_slug'=>'required|alpha_dash|max:100|unique:tenant_registration_requests,requested_slug|unique:tenants,slug','constitution_type'=>'required|string|max:50','home_region'=>'required|in:ap-south-1,eu-central-1,us-east-1','country_code'=>'required|size:2','timezone'=>'required|max:50','default_language'=>'required|max:10','default_currency'=>'required|size:3','admin.first_name'=>'required|max:100','admin.last_name'=>'nullable|max:100','admin.email'=>'required|email|max:254','admin.phone'=>['required','regex:/^\+[1-9][0-9]{7,14}$/'],'tax_identifiers'=>'array|max:5','tax_identifiers.*.type'=>'required|max:30','tax_identifiers.*.value'=>'required|max:100','documents'=>'array|max:10','documents.*.type'=>'required|max:50','documents.*.number'=>'nullable|max:150']);$email=$identity->email($d['admin']['email']);$phone=$identity->phone($d['admin']['phone']);abort_if(User::where('email_hash',$email['hash'])->orWhere('phone_hash',$phone['hash'])->exists(),422,'Use the existing account to register another institution.');$token=Str::random(64);[$reg,$user]=DB::transaction(function()use($d,$email,$phone,$sensitive,$token){$user=User::create(['public_id'=>(string)Str::ulid(),'identity_region'=>$d['home_region'],'first_name'=>$d['admin']['first_name'],'last_name'=>$d['admin']['last_name']??null,'display_name'=>trim($d['admin']['first_name'].' '.($d['admin']['last_name']??'')),'email_encrypted'=>$email['encrypted'],'email_hash'=>$email['hash'],'email_masked'=>$email['masked'],'phone_encrypted'=>$phone['encrypted'],'phone_hash'=>$phone['hash'],'phone_masked'=>$phone['masked'],'status'=>'pending_verification','registered_via'=>'tenant_self_registration','registration_started_at'=>now(),'verification_expires_at'=>now()->addDay()]);$reg=TenantRegistrationRequest::create([...collect($d)->except(['admin','tax_identifiers','documents'])->all(),'public_id'=>(string)Str::ulid(),'applicant_user_id'=>$user->id,'registration_token_hash'=>hash('sha256',$token)]);foreach($d['tax_identifiers']??[]as$x){$p=$sensitive->protect($x['value']);$reg->taxIdentifiers()->create(['identifier_type'=>$x['type'],'country_code'=>$d['country_code'],'identifier_encrypted'=>$p['encrypted'],'identifier_hash'=>$p['hash'],'masked_value'=>$p['masked'],'registered_legal_name'=>$d['legal_name']??$d['institution_name']]);}foreach($d['documents']??[]as$x){$p=!empty($x['number'])?$sensitive->protect($x['number']):null;$reg->documents()->create(['document_type'=>$x['type'],'document_number_encrypted'=>$p['encrypted']??null,'document_number_hash'=>$p['hash']??null,'masked_number'=>$p['masked']??null,'issuing_country_code'=>$d['country_code']]);}return[$reg,$user];});foreach(['email','sms']as$c){$otp=(string)random_int(100000,999999);VerificationChallenge::create(['public_id'=>(string)Str::ulid(),'user_id'=>$user->id,'channel'=>$c,'purpose'=>'tenant_registration','destination_hash'=>$c==='email'?$email['hash']:$phone['hash'],'otp_hash'=>Hash::make($otp),'status'=>'pending','expires_at'=>now()->addMinutes(5),'maximum_attempts'=>5,'last_sent_at'=>now(),'request_ip'=>$r->ip()]);$sender->send($c,$c==='email'?$d['admin']['email']:$d['admin']['phone'],$otp,'tenant_registration');}return response()->json(['data'=>['request_id'=>$reg->public_id,'verification_token'=>$token,'status'=>$reg->status]],201);}
public function verify(Request $r,TenantRegistrationRequest $registration):JsonResponse{$d=$r->validate(['verification_token'=>'required','channel'=>'required|in:email,sms','otp'=>'required|digits:6']);abort_unless(hash_equals($registration->registration_token_hash,hash('sha256',$d['verification_token'])),404);$c=VerificationChallenge::where(['user_id'=>$registration->applicant_user_id,'channel'=>$d['channel'],'purpose'=>'tenant_registration','status'=>'pending'])->latest()->firstOrFail();abort_if($c->expires_at->isPast(),422,'OTP expired.');$c->increment('attempt_count');abort_unless(Hash::check($d['otp'],$c->otp_hash),422,'Invalid OTP.');$c->update(['status'=>'verified','verified_at'=>now()]);$column=$d['channel']==='email'?'email_verified_at':'phone_verified_at';$registration->applicant->forceFill([$column=>now()])->save();if($registration->applicant->email_verified_at&&$registration->applicant->phone_verified_at){$registration->update(['status'=>'submitted','submitted_at'=>now()]);$registration->applicant->update(['status'=>'pending_approval','registration_completed_at'=>now()]);}return response()->json(['data'=>['request_id'=>$registration->public_id,'status'=>$registration->fresh()->status]]);}}
